-- All fixtures, checks and history roll back. No production patient is changed.
begin;
do $$ declare
 au uuid:=gen_random_uuid();su uuid:=gen_random_uuid();pu uuid:=gen_random_uuid();ou uuid:=gen_random_uuid();
 ap uuid:=gen_random_uuid();sp uuid:=gen_random_uuid();pp uuid:=gen_random_uuid();op uuid:=gen_random_uuid();
 d uuid:=gen_random_uuid();version uuid;mid uuid;item uuid;unmapped uuid;
 first_op uuid:=gen_random_uuid();second_op uuid:=gen_random_uuid();restore_op uuid:=gen_random_uuid();r jsonb;day date:=(now() at time zone 'America/Sao_Paulo')::date;
begin
 if (select count(*) from public.taco_foods where reference_source='taco')<>597 or (select kcal_per_100g from public.taco_foods where id=91)<>52 then raise exception 'FAIL official reference';end if;
 insert into auth.users(id,email) values(au,'qa-'||au||'@example.invalid'),(su,'qa-'||su||'@example.invalid'),(pu,'qa-'||pu||'@example.invalid'),(ou,'qa-'||ou||'@example.invalid');
 insert into public.profiles(id,user_id,username,full_name,role) values(ap,au,'qa-'||au,'QA nutri','admin'),(sp,su,'qa-'||su,'QA secretária','secretary'),(pp,pu,'qa-'||pu,'QA paciente','patient'),(op,ou,'qa-'||ou,'QA outro','patient');
 insert into public.staff_permissions(user_id,enabled) values(su,true);
 insert into public.diets(id,patient_id,title,status) values(d,pp,'QA base','draft');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',su,'role','authenticated','aal','aal1')::text,true);execute 'set local role authenticated';
 version:=public.save_diet_version(d,jsonb_build_object('title','QA plano','status','active','meals',jsonb_build_array(jsonb_build_object('name','Almoço','options',jsonb_build_array(jsonb_build_object('name','Opção 1','items',jsonb_build_array(jsonb_build_object('food_name','Batata inglesa cozida','quantity','200','unit','g','taco_food_id',91,'portion_g',200),jsonb_build_object('food_name','Alimento sem referência','quantity','1 unidade'))))))));
 select m.id,i.id into mid,item from public.diet_meals m join public.diet_items i on i.meal_id=m.id where m.diet_id=version and i.taco_food_id=91;
 if item is null or (select portion_g from public.diet_items where id=item)<>200 then raise exception 'FAIL versioned reference/weight';end if;
 select i.id into unmapped from public.diet_items i where i.meal_id=mid and i.taco_food_id is null;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pu,'role','authenticated')::text,true);
 insert into public.patient_item_checks(patient_id,item_id,check_date) values(pp,item,day);
 r:=public.save_food_substitution(first_op,item,3,day,null);
 if (r->'substitution'->>'energy_kcal')::numeric<>104 or (r->'substitution'->>'target_grams')::numeric<>81.25 then raise exception 'FAIL calorie-only math';end if;
 if (select count(*) from public.patient_saved_substitutions where patient_id=pp and source_food_id=91 and target_food_id=3)<>1 then raise exception 'FAIL reusable saved replacement';end if;
 if exists(select 1 from public.patient_item_checks where patient_id=pp and item_id=item and check_date=day) then raise exception 'FAIL replacement claims consumption';end if;
 if (select food_name from public.diet_items where id=item)<>'Batata inglesa cozida' or (select quantity from public.diet_items where id=item)<>'200' then raise exception 'FAIL prescription changed';end if;
 r:=public.save_food_substitution(first_op,item,3,day,null);
 if not (r->>'replayed')::boolean or (select count(*) from public.clinical_records where id=first_op)<>1 then raise exception 'FAIL retry duplicated history';end if;
 begin perform public.save_food_substitution(gen_random_uuid(),item,88,day,null);raise exception 'FAIL stale overwrite';exception when serialization_failure then null;end;
 r:=public.save_food_substitution(second_op,item,88,day,first_op);
 r:=public.save_food_substitution(first_op,item,3,day,null);
 if r->'substitution'->>'id'<>second_op::text or (select target_food_id from public.patient_food_substitutions where item_id=item)<>88 then raise exception 'FAIL stale retry reverted newer choice';end if;
 begin perform public.save_food_substitution(gen_random_uuid(),unmapped,3,day,null);raise exception 'FAIL guessed missing reference';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 begin perform public.save_food_substitution(gen_random_uuid(),item,450,day,second_op);raise exception 'FAIL unknown energy accepted';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 begin perform public.save_food_substitution(gen_random_uuid(),item,3,day-1,second_op);raise exception 'FAIL past date changed';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 begin update public.patient_food_substitutions set target_grams=999 where item_id=item;raise exception 'FAIL direct forged quantity';exception when insufficient_privilege then null;end;
 begin update public.taco_foods set kcal_per_100g=1 where id=3;raise exception 'FAIL catalog write';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ou,'role','authenticated')::text,true);
 if exists(select 1 from public.patient_food_substitutions where patient_id=pp) then raise exception 'FAIL patient isolation';end if;
 if exists(select 1 from public.patient_saved_substitutions where patient_id=pp) then raise exception 'FAIL saved replacement isolation';end if;
 begin perform public.save_food_substitution(gen_random_uuid(),item,3,day,second_op);raise exception 'FAIL foreign diet substitution';exception when insufficient_privilege then null;end;
 begin perform public.remove_food_substitution(second_op,gen_random_uuid());raise exception 'FAIL foreign removal';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',su,'role','authenticated','aal','aal1')::text,true);
 if (select count(*) from public.patient_food_substitutions where patient_id=pp)<>1 then raise exception 'FAIL staff cannot see replacement';end if;
 perform public.remove_food_substitution(second_op,restore_op);perform public.remove_food_substitution(second_op,restore_op);
 if exists(select 1 from public.patient_food_substitutions where item_id=item) or (select count(*) from public.clinical_records where patient_id=pp and payload->>'category'='meal_substitution')<>3 then raise exception 'FAIL restore/history';end if;
 if (select count(*) from public.patient_saved_substitutions where patient_id=pp)<>2 then raise exception 'FAIL restoration removed reusable choices';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pu,'role','authenticated')::text,true);
 r:=public.save_food_substitution(second_op,item,88,day,first_op);
 if r->'substitution'<>'null'::jsonb or not (r->>'replayed')::boolean or exists(select 1 from public.patient_food_substitutions where item_id=item) then raise exception 'FAIL stale retry recreated a restored replacement';end if;
 perform public.forget_saved_substitution(91,3);
 if (select count(*) from public.patient_saved_substitutions where patient_id=pp)<>1 then raise exception 'FAIL forgetting reusable choice';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated','aal','aal1')::text,true);
 if not exists(select 1 from public.clinic_audit where source='patient_food_substitutions' and actor_id=sp and action='delete') then raise exception 'FAIL secretary audit';end if;
 if has_function_privilege('anon','public.save_food_substitution(uuid,uuid,integer,date,uuid)','EXECUTE') then raise exception 'FAIL anonymous operation';end if;
end $$;
rollback;
